Q: blob size on client sometimes is smaller then the file sent from server
A: <p>I found the mistake:</p>
<pre><code>function writeFile(fileStream, fileName) {
    return new Promise(function (resolve, reject) {
        var file = fs.createWriteStream(fileName);
        fileStream.pipe(file);
        filestream.on('finish', () =&gt; { //this should be concat to filestream.pipe(file)

        resolve();
        });;
    });
}
</code></pre>
<p>so the solution:</p>
<pre><code>function writeFile(fileStream, fileName) {
    return new Promise(function (resolve, reject) {
        var file = fs.createWriteStream(fileName);
        fileStream.pipe(file).on('finish', () =&gt; {

            resolve();
        });;
    });
}
</code></pre>
<p>Now blob size is consistent between server and client</p>

