Q: How do I close all popups with .removeclass or .toggleclass
A: <p>I will give you another approach to these popups. I have commented the code. If it is unclear, please add a comment.</p>
<p>This way you can add many popups without changing your js.</p>
<p>PS: Please note that I have changed some CSS for the snippet to be working. Also, some HTML is changed to accomplish the idea of multiple popups, which will be ideal for your case with many popups in this pie chart.</p>
<p><div class="snippet" data-lang="js" data-hide="false" data-console="true" data-babel="false">
<div class="snippet-code">
<pre class="snippet-code-js lang-js prettyprint-override"><code>const popups = document.querySelectorAll('.popup');
const buttons = document.querySelectorAll('.js-toggle-modal');
const closeButtons = document.querySelectorAll('.js-modal-close');

const closeModals = () =&gt; {
  // Iterate through all popups and remove class show
  popups.forEach(popup =&gt; {
    popup.classList.remove('show');
  })
}

closeButtons.forEach(button =&gt; {
  // Close all popups on close button click
  button.addEventListener('click', function(e) {
    e.preventDefault();

    closeModals();
  })
});

buttons.forEach(button =&gt; {
  // Cache target of each button
  const target = document.querySelector(button.getAttribute('data-target'));

  button.addEventListener('click', function(e) {
    e.preventDefault();

    // Hide all active popups
    closeModals();

    // Show current target popup
    target.classList.add('show');
  });
});</code></pre>
