Q: ExtJS - saving data in multiple stores
A: <p>I've ended up using something like Drasill suggested, but it got a bit messy. I imagine it would screw up if you called it twice without waiting for the first time to finish, because of the way the events work.</p>

<pre><code>var save_multiple_stores = function(stores, success, fail) {
    if (stores.length === 0) {
        if (success) {
            success();
        }
    } else {
        var store = stores.pop();

        var listeners = {}

        var unbind_listeners = function() {
           for (var evt in listeners) {
                store.un(evt, listeners[evt]);
           }
        }

        var onsuccess = function() {
            unbind_listeners();
            save_multiple_stores(stores, success, fail);
        }

        var onfail = function() {
            unbind_listeners();
            if (fail) {
                fail();
            }
        }

        store.on('save', onsuccess);
        listeners.save = onsuccess;
        store.on('exception', onfail);
        listeners.exception = onfail;

        var num_records = store.save();
        //save event will not fire if there are no changed records
        if (num_records &lt;= 0) {
            onsuccess();
        }
    }
};
</code></pre>

