Q: Node Async/Await Recursive Function ends code execution
A: <p>Here are some ways to fix it:</p>

<pre><code>function promiseFunc(number) {
    return new Promise((resolve, reject) =&gt; {
        if (number == 100) {
            console.log('Inside Promise');
            resolve('Done');
        } else {
            number += 1;
            resolve(promiseFunc(number));
        }
    })
}


(async function testFunc() {
    console.log('Starting');
    await promiseFunc(0)
    console.log("Test completed");
})()
</code></pre>

<p>Or, interestingly enough, the equivalent code that uses <code>async</code>/<code>await</code> instead of explicit <code>new Promise(...)</code>, works for your case:</p>

<pre><code>// an async function returns a Promise
async function promiseFunc(number) {
        if (number == 100) {
            console.log('Inside Promise');
            return 'Done';
        } else {
            number += 1;
            // it seems to work as intended without saying return promiseFunc(...)
            promiseFunc(number);
        }
    }


(async function testFunc() {
    console.log('Starting');
    await promiseFunc(0)
    console.log("Test completed");
})()
