      switch(used_as_a_y) {
        case WestWall:
        case EastWall:
        case NorthWall:
        case EastWall:
          return true;
        default: break;
      }
    }
    default: break;
  }
  switch(used_as_a_y) {
    case Wall: {
      switch(x) {
        case WestWall:
        case EastWall:
        case NorthWall:
        case EastWall:
